/*
 * A191130  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then 3x and 4x+2 are in a.
 * https://oeis.org/A191130
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   Sequence generated by a(1)=1; if x∈a then 3·x and 4·x+2 are in
 *            a. This function computes a(n) by iteratively merging the two
 *            generating sequences using a simple cache. It works for any
 *            build-defined seq_t and idx_t
 * Range:     u8 n <= 26, u16 n <= 588, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdbool.h>
#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static cache of computed terms */
    static seq_t *cache = NULL;
    static size_t  cache_cap = 0;   /* allocated capacity */
    static idx_t   cache_size = 0;  /* number of terms stored */

    /* stream cursor indices for the two generators */
    static idx_t ptr3 = 0;
    static idx_t ptr4 = 0;

    if (n == 0)                 /* undefined below offset */
        return (seq_t)0;

    /* grow the cache until it contains at least n terms */
    while (cache_size < (size_t)n) {
        /* first element */
        if (cache_size == 0) {
            if (cache_cap == 0) {
                cache_cap = 16;
                cache = (seq_t*)malloc(cache_cap * sizeof(seq_t));
                if (!cache) return (seq_t)0;   /* allocation fail */
            }
            cache[0] = (seq_t)1;
            cache_size = 1;
            continue;
        }

        /* resize if needed */
        if (cache_size == cache_cap) {
            size_t new_cap = cache_cap << 1;
            seq_t *tmp = (seq_t*)realloc(cache, new_cap * sizeof(seq_t));
            if (!tmp) return (seq_t)0;
            cache = tmp;
            cache_cap = new_cap;
        }

        /* compute the two next candidates */
        seq_t cand3 = (seq_t)3 * cache[(size_t)ptr3];
        seq_t cand4 = (seq_t)4 * cache[(size_t)ptr4] + (seq_t)2;

        /* decide which candidate to output next */
        seq_t next;
        bool use3 = false, use4 = false;

        if (cand3 < cand4) {
            next = cand3;
            use3 = true;
        } else if (cand4 < cand3) {
            next = cand4;
            use4 = true;
        } else {                /* equal */
            next = cand3;
            use3 = use4 = true;
        }

        /* append the next term and advance pointers */
        cache[cache_size++] = next;
        if (use3) ptr3++;
        if (use4) ptr4++;
    }

    return cache[(size_t)n - 1];
}
